import{c as t,Q as a,j as r,m as l}from"./chunks/framework.BPKcPtvA.js";const m=JSON.parse('{"title":"机器人使用详解 - Telegram 指令与菜单操作","description":"完全掌握 /start、/detect、/recovery 等 Telegram 快捷指令。解决输入私钥、输入地址时的常见格式错误。","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://hyperliquidrecoverybot.github.io/zh/bot-usage"}],["link",{"rel":"alternate","hreflang":"en","href":"https://hyperliquidrecoverybot.github.io/en/bot-usage"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://hyperliquidrecoverybot.github.io/zh/bot-usage"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://hyperliquidrecoverybot.github.io/en/bot-usage"}],["meta",{"name":"keywords","content":"Telegram机器人指令, 找回机器人操作, 钱包恢复步骤, 交互界面说明"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"机器人使用详解 - Telegram 指令与菜单操作"}],["meta",{"property":"og:description","content":"完全掌握 /start、/detect、/recovery 等 Telegram 快捷指令。解决输入私钥、输入地址时的常见格式错误。"}],["meta",{"property":"og:url","content":"https://hyperliquidrecoverybot.github.io/zh/bot-usage"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"机器人使用详解 - Telegram 指令与菜单操作"}],["meta",{"name":"twitter:description","content":"完全掌握 /start、/detect、/recovery 等 Telegram 快捷指令。解决输入私钥、输入地址时的常见格式错误。"}]]},"headers":[],"relativePath":"zh/bot-usage.md","filePath":"zh/bot-usage.md","lastUpdated":null}'),i={name:"zh/bot-usage.md"};function o(d,e,c,n,h,s){return a(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="机器人使用" tabindex="-1">机器人使用 <a class="header-anchor" href="#机器人使用" aria-label="Permalink to &quot;机器人使用&quot;">​</a></h1><p>本页说明常用命令、标准操作路径和结果阅读方式。</p><h2 id="命令总览" tabindex="-1">命令总览 <a class="header-anchor" href="#命令总览" aria-label="Permalink to &quot;命令总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>/start</code></td><td>打开主菜单</td></tr><tr><td><code>/detect</code></td><td>进入地址检测</td></tr><tr><td><code>/recovery</code></td><td>进入资产恢复</td></tr></tbody></table><h2 id="标准操作路径" tabindex="-1">标准操作路径 <a class="header-anchor" href="#标准操作路径" aria-label="Permalink to &quot;标准操作路径&quot;">​</a></h2><ol><li><code>/start</code> 初始化会话</li><li><code>/detect</code> 查看资产结构</li><li><code>/recovery</code> 输入地址与凭证</li><li>确认恢复计划与费用明细</li><li>等待恢复流程完成，并保留交易哈希以便需要时自行核对</li></ol><h2 id="交互要点" tabindex="-1">交互要点 <a class="header-anchor" href="#交互要点" aria-label="Permalink to &quot;交互要点&quot;">​</a></h2><ul><li>检测阶段为只读操作，且无需私钥</li><li>恢复阶段支持私钥或助记词</li><li>无需填写目标地址，资金会回到源地址对应的 Arbitrum 地址</li><li>有锁定/等待资产时，机器人会提示再次运行时间</li></ul><h2 id="结果阅读" tabindex="-1">结果阅读 <a class="header-anchor" href="#结果阅读" aria-label="Permalink to &quot;结果阅读&quot;">​</a></h2><p>恢复完成后重点关注：</p><ul><li>恢复金额（<code>Recovered Amount</code>）</li><li>实际费用（<code>Actual Fees</code>）</li><li>服务费（<code>Service Fee</code>）</li><li>提现手续费（<code>Withdrawal Fees</code>）</li><li>交易哈希（如需自行核对可查看）</li></ul><p>提现发起后到 Arbitrum 的到账是异步的，受 Hyperliquid 处理速度影响，可能需要几分钟到十几分钟。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li>只跑恢复不先检测：容易忽略锁定资产状态</li><li>把预估值当最终值：执行期价格会有轻微变化</li><li>未确认源地址在 Arbitrum 的接收可用性：可能导致到账体验不一致</li></ul><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./address-detection">地址检测</a></li><li><a href="./asset-recovery">资产恢复</a></li><li><a href="./fee-and-settlement">费用与到账</a></li><li><a href="./execution-status">执行状态说明</a></li></ul>',16)])])}const b=t(i,[["render",o]]);export{m as __pageData,b as default};
